useEffectOnce.code_template:
const useEffectOnce = (effect: () => void | (() => void)) => {
  const hasRun = useRef(false);
  useEffect(() => {
    if (!hasRun.current) {
      hasRun.current = true;
      return effect();
    }
  }, []);
};

useClientOnly.code_template:
const useClientOnly = () => {
  const [isClient, setIsClient] = useState(false);
  useEffect(() => setIsClient(true), []);
  return isClient;
};

useAbortSafe.code_template:
const useAbortSafe = () => {
  const abortRef = useRef<AbortController>();
  const isMounted = useRef(true);

  const getController = () => {
    if (!abortRef.current) {
      abortRef.current = new AbortController();
    }
    return abortRef.current;
  };

  useEffect(() => {
    return () => {
      isMounted.current = false;
      if (abortRef.current && !document.hidden) {
        abortRef.current.abort();
      }
    };
  }, []);

  return { getController, isMounted };
};

useMountedRef.code_template:
const useMountedRef = () => {
  const mounted = useRef(true);
  useEffect(() => {
    return () => { mounted.current = false; };
  }, []);
  return mounted;
};

useHydrated.code_template:
const useHydrated = () => {
  const [hydrated, setHydrated] = useState(false);
  useEffect(() => {
    setHydrated(true);
  }, []);
  return hydrated;
};
